package com.meterflow.credits;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import java.math.*;import java.util.*;
@RestController @RequestMapping("/api/credits")public class CreditController{private final CreditService service;public CreditController(CreditService s){service=s;}public record CreditInput(@NotBlank String customerId,@NotBlank String currency,@NotNull @DecimalMin("0.01") BigDecimal amount){}public record NoteInput(@NotBlank String customerId,@NotBlank String currency,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotBlank String reason){}
@GetMapping public CreditAccount balance(@RequestParam String customerId,Authentication a){guard(customerId,a);return service.balance(customerId);}@GetMapping("/notes")public List<CreditNote> notes(@RequestParam String customerId,Authentication a){guard(customerId,a);return service.notes(customerId);}
@PreAuthorize("hasRole('ADMIN')")@PostMapping("/top-up")public CreditAccount topup(@Valid @RequestBody CreditInput i){return service.topUp(i.customerId(),i.currency(),i.amount());}@PreAuthorize("hasRole('ADMIN')")@PostMapping("/notes")public CreditNote note(@Valid @RequestBody NoteInput i){return service.issueNote(i.customerId(),i.currency(),i.amount(),i.reason());}
private void guard(String c,Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN"))&&!a.getName().equals(c))throw new org.springframework.security.access.AccessDeniedException("Customer access denied");}}
